From de9a4639799e83709f1c506e4c0799e490d4b94e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 04:18:05 +0100
Subject: [PATCH] folder: use the listed root item for the widget icon

The icon was taken from a KFileItem built from the bare URL, which can't
know the type of virtual locations like applications:/Games/ and showed
the unknown icon. Use the lister's root item once listed, like Dolphin.

BUG: 294572
---
 containments/desktop/plugins/folder/foldermodel.cpp | 4 +++-
 1 file changed, 3 insertions(+), 1 deletion(-)

diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..6b29869afb 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -231,6 +231,7 @@ FolderModel::FolderModel(QObject *parent)
     QObject::connect(dirLister, &KCoreDirLister::completed, this, [this, dirLister] {
         setStatus(Status::Ready);
         Q_EMIT listingCompleted(dirLister->items().urlList());
+        Q_EMIT iconNameChanged();
     });

     QObject::connect(dirLister, &KCoreDirLister::canceled, this, [this] {
@@ -495,7 +496,8 @@ QUrl FolderModel::resolve(const QString &url)

 QString FolderModel::iconName() const
 {
-    const KFileItem rootItem(m_dirModel->dirLister()->url());
+    const KFileItem listedRootItem = m_dirModel->dirLister()->rootItem();
+    const KFileItem rootItem = listedRootItem.isNull() ? KFileItem(m_dirModel->dirLister()->url()) : KFileItem(listedRootItem.entry(), listedRootItem.url());

     if (!rootItem.isFinalIconKnown()) {
         rootItem.determineMimeType();
